// Sportmonks API Service
// Documentation: https://docs.sportmonks.com/football/

const API_KEY = process.env.NEXT_PUBLIC_SPORTMONKS_API_KEY;
const BASE_URL = process.env.SPORTMONKS_API_URL || 'https://api.sportmonks.com/v3';
const REAL_MADRID_ID = 53; // Real Madrid team ID in Sportmonks

export interface SportmonksFixture {
  id: number;
  name: string;
  starting_at: string;
  result_info: string | null;
  league_id: number;
  season_id: number;
  round_id: number | null;
  state_id: number;
  venue_id: number | null;
  length: number | null;
  starting_at_timestamp: number;
  participants?: {
    id: number;
    name: string;
    short_code: string;
    image_path: string;
    location: 'home' | 'away';
    meta?: {
      winner?: boolean;
    };
  }[];
  scores?: {
    participant_id: number;
    score: {
      goals: number;
    };
  }[];
  league?: {
    id: number;
    name: string;
    short_code: string;
    image_path: string;
  };
  venue?: {
    id: number;
    name: string;
    city_name: string;
  };
  state?: {
    id: number;
    state: string;
    name: string;
    short_name: string;
  };
}

export interface FormattedMatch {
  id: number;
  homeTeam: string;
  awayTeam: string;
  homeScore: number | null;
  awayScore: number | null;
  date: string;
  time: string;
  venue: string;
  league: string;
  leagueShortCode: string;
  status: string;
  isHome: boolean;
  isCompleted: boolean;
}

/**
 * Fetch upcoming fixtures for Real Madrid
 */
export async function getRealMadridFixtures(
  status: 'upcoming' | 'finished' | 'all' = 'upcoming',
  limit: number = 10
): Promise<FormattedMatch[]> {
  try {
    const endpoint = status === 'finished' 
      ? `football/fixtures?api_token=${API_KEY}&include=participants;scores;league;venue;state&filter[fixture_states]=5,12` // Finished states
      : `football/fixtures?api_token=${API_KEY}&include=participants;scores;league;venue;state&filter[fixture_states]=1,2,10,11`; // Upcoming states
    
    const response = await fetch(
      `${BASE_URL}/${endpoint}&filter[team_id]=${REAL_MADRID_ID}&per_page=${limit}`,
      {
        headers: {
          'Accept': 'application/json',
        },
        next: { revalidate: 3600 } // Cache for 1 hour
      }
    );

    if (!response.ok) {
      throw new Error(`API Error: ${response.status}`);
    }

    const data = await response.json();
    
    if (!data.data || !Array.isArray(data.data)) {
      console.warn('No fixtures data returned from API');
      return [];
    }

    return formatFixtures(data.data);
  } catch (error) {
    console.error('Error fetching fixtures:', error);
    return [];
  }
}

/**
 * Fetch next upcoming match for Real Madrid
 */
export async function getNextMatch(): Promise<FormattedMatch | null> {
  try {
    const fixtures = await getRealMadridFixtures('upcoming', 1);
    return fixtures[0] || null;
  } catch (error) {
    console.error('Error fetching next match:', error);
    return null;
  }
}

/**
 * Format raw API data into usable match objects
 */
function formatFixtures(fixtures: SportmonksFixture[]): FormattedMatch[] {
  return fixtures.map((fixture): FormattedMatch => {
    const participants = fixture.participants || [];
    const homeTeam = participants.find(p => p.location === 'home');
    const awayTeam = participants.find(p => p.location === 'away');
    
    // Determine if Real Madrid is playing at home
    const isHome = homeTeam?.id === REAL_MADRID_ID;
    
    // Get scores if available
    const homeScore = fixture.scores?.find(s => s.participant_id === homeTeam?.id)?.score.goals ?? null;
    const awayScore = fixture.scores?.find(s => s.participant_id === awayTeam?.id)?.score.goals ?? null;
    
    // Format date
    const matchDate = new Date(fixture.starting_at);
    const dateStr = matchDate.toLocaleDateString('en-GB', {
      weekday: 'short',
      day: 'numeric',
      month: 'short',
    });
    const timeStr = matchDate.toLocaleTimeString('en-GB', {
      hour: '2-digit',
      minute: '2-digit',
    });
    
    // Get match status
    const state = fixture.state;
    const isCompleted = state?.id === 5 || state?.id === 12; // Finished states
    
    return {
      id: fixture.id,
      homeTeam: homeTeam?.name || 'TBD',
      awayTeam: awayTeam?.name || 'TBD',
      homeScore,
      awayScore,
      date: dateStr,
      time: timeStr,
      venue: fixture.venue?.name || 'TBD',
      league: fixture.league?.name || 'Unknown League',
      leagueShortCode: fixture.league?.short_code || '',
      status: state?.name || 'Scheduled',
      isHome,
      isCompleted,
    };
  });
}

/**
 * Get team standings/league table
 */
export async function getLeagueStandings(seasonId: number = 21646): Promise<any[]> {
  try {
    const response = await fetch(
      `${BASE_URL}/football/standings/season/${seasonId}?api_token=${API_KEY}&include=participant;league`,
      {
        headers: {
          'Accept': 'application/json',
        },
        next: { revalidate: 3600 }
      }
    );

    if (!response.ok) {
      throw new Error(`API Error: ${response.status}`);
    }

    const data = await response.json();
    return data.data || [];
  } catch (error) {
    console.error('Error fetching standings:', error);
    return [];
  }
}
